package stowage

import (
	"math"
	"sort"
	"strconv"
	"strings"
)

// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
//
// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
// 可以修正后重试。内容比较按编号去空白后的原始字节进行：登记处能
// 区分的编号（包括含无效 UTF-8 字节的编号）在内容判断中同样区分。
// 卸下操作忽略目标值，其目标不参与内容比较；装载与移动的目标舱位
// 参与比较。
//
// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
// 范围也会被拒绝。
func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	aid := strings.TrimSpace(adjustmentID)
	if aid == "" {
		return nil, fail(ErrInvalidID, "", "调整编号为空")
	}

	// f 构造带调整编号的错误。
	f := func(kind ErrorKind, id string, format string, args ...any) *Error {
		e := fail(kind, id, format, args...)
		e.AdjustmentID = aid
		return e
	}

	// 幂等：编号已成功使用过。
	if saved, ok := r.adjustments[aid]; ok {
		if r.contents[aid] == canonicalKey(ops) {
			return cloneResult(saved), nil
		}
		return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
	}

	if len(ops) == 0 {
		return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
	}

	vops, final, affected, err := r.prepareOps(ops, f)
	if err != nil {
		return nil, err
	}

	// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整；
	// 拒绝原因到结构化错误的转换与 AmendCargo 共用。
	if rej := r.firstRejection(final); rej != nil {
		return nil, rejectionError(rej, f)
	}

	// 全部合法，正式生效。先计算受影响舱位调整前后的重量。
	cargoChanges := make([]CargoChange, 0, len(vops))
	compChanges := make([]CompartmentChange, 0, len(affected))
	for id := range affected {
		compChanges = append(compChanges, CompartmentChange{
			CompartmentID: id,
			WeightBefore:  sumSet(r.compartments[id].cargo),
			WeightAfter:   sumSet(final[id]),
		})
	}
	sort.Slice(compChanges, func(i, j int) bool {
		return compChanges[i].CompartmentID < compChanges[j].CompartmentID
	})

	for _, v := range vops {
		c := v.cargo
		from := c.compartmentID
		var to string
		switch v.op.Kind {
		case OpLoad:
			r.compartments[v.target.id].cargo[c.id] = c
			c.compartmentID = v.target.id
			to = v.target.id
		case OpUnload:
			delete(r.compartments[from].cargo, c.id)
			c.compartmentID = ""
		case OpMove:
			delete(r.compartments[from].cargo, c.id)
			r.compartments[v.target.id].cargo[c.id] = c
			c.compartmentID = v.target.id
			to = v.target.id
		}
		cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
	}
	sort.Slice(cargoChanges, func(i, j int) bool {
		return cargoChanges[i].CargoID < cargoChanges[j].CargoID
	})

	result := &AdjustmentResult{
		ID:                 aid,
		CargoChanges:       cargoChanges,
		CompartmentChanges: compChanges,
	}
	r.adjustments[aid] = result
	r.contents[aid] = canonicalKey(ops)
	return cloneResult(result), nil
}

// validOp 是一条通过逐条校验的操作，附带其涉及的内部记录。
type validOp struct {
	op     Op
	cargo  *cargo
	target *compartment // 装载/移动的目标舱位；卸下时为 nil
}

// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
// 目标舱位（交换中的两个舱位都会纳入）。
func (r *Registry) prepareOps(
	ops []Op,
	failf func(kind ErrorKind, id string, format string, args ...any) *Error,
) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
	seen := make(map[string]bool)
	vops = make([]validOp, 0, len(ops))
	affected = make(map[string]bool)

	for _, op := range ops {
		cid := strings.TrimSpace(op.CargoID)
		if cid == "" {
			return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
		}
		c, ok := r.cargos[cid]
		if !ok {
			return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
		}
		if seen[cid] {
			return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
		}
		seen[cid] = true

		switch op.Kind {
		case OpLoad:
			if c.compartmentID != "" {
				return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
			}
			tid := strings.TrimSpace(op.Target)
			if tid == "" {
				return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
			}
			t, ok := r.compartments[tid]
			if !ok {
				return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
			}
			vops = append(vops, validOp{op, c, t})
			affected[t.id] = true
		case OpUnload:
			if c.compartmentID == "" {
				return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
			}
			vops = append(vops, validOp{op, c, nil})
			affected[c.compartmentID] = true
		case OpMove:
			if c.compartmentID == "" {
				return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
			}
			tid := strings.TrimSpace(op.Target)
			if tid == "" {
				return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
			}
			t, ok := r.compartments[tid]
			if !ok {
				return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
			}
			if t.id == c.compartmentID {
				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
			}
			vops = append(vops, validOp{op, c, t})
			affected[c.compartmentID] = true
			affected[t.id] = true
		default:
			return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
		}
	}

	// 在模拟配载上应用全部操作，判断以完成后的最终状态为准。
	final = make(map[string]map[string]*cargo, len(r.compartments))
	for id, comp := range r.compartments {
		set := make(map[string]*cargo, len(comp.cargo))
		for cid, c := range comp.cargo {
			set[cid] = c
		}
		final[id] = set
	}
	for _, v := range vops {
		switch v.op.Kind {
		case OpLoad:
			final[v.target.id][v.cargo.id] = v.cargo
		case OpUnload:
			delete(final[v.cargo.compartmentID], v.cargo.id)
		case OpMove:
			delete(final[v.cargo.compartmentID], v.cargo.id)
			final[v.target.id][v.cargo.id] = v.cargo
		}
	}
	return vops, final, affected, nil
}

// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
// 调用方必须持有 r.mu。
func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
	var rejs []*Rejection
	for id, set := range final {
		comp := r.compartments[id]

		// 重量原因：溢出优先，溢出时不提供任何重量数值。
		var sum int64
		overflow := false
		for _, c := range set {
			if c.weight > math.MaxInt64-sum {
				overflow = true
				break
			}
			sum += c.weight
		}
		var rej *Rejection
		if overflow {
			rej = &Rejection{
				CompartmentID: id,
				Kind:          ErrOverflow,
				MaxWeight:     comp.maxWeight,
			}
		} else if sum > comp.maxWeight {
			rej = &Rejection{
				CompartmentID:   id,
				Kind:            ErrOverweight,
				MaxWeight:       comp.maxWeight,
				UsedWeight:      sum,
				RemainingWeight: comp.maxWeight - sum,
				Overweight:      sum - comp.maxWeight,
			}
		}

		// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
		destinations := make(map[string][]string)
		destSet := make(map[string]bool)
		var offenders []string
		for _, c := range set {
			destinations[c.destination] = append(destinations[c.destination], c.id)
			destSet[c.destination] = true
			if !c.allowMixed {
				offenders = append(offenders, c.id)
			}
		}
		if len(destSet) > 1 && len(offenders) > 0 {
			dests := make([]MixedDestination, 0, len(destinations))
			for dest, ids := range destinations {
				sorted := append([]string(nil), ids...)
				sort.Strings(sorted)
				dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
			}
			sort.Slice(dests, func(i, j int) bool {
				return dests[i].Destination < dests[j].Destination
			})
			sort.Strings(offenders)
			mr := &Rejection{
				CompartmentID:  id,
				Kind:           ErrMixedLoading,
				MaxWeight:      comp.maxWeight,
				Destinations:   dests,
				OffendingCargo: offenders,
			}
			if rej != nil {
				rejs = append(rejs, rej, mr)
			} else {
				rejs = append(rejs, mr)
			}
		} else if rej != nil {
			rejs = append(rejs, rej)
		}
	}
	return rejs
}

// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
// 调用方必须持有 r.mu。
func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
	rejs := r.evaluateFinal(final)
	if len(rejs) == 0 {
		return nil
	}
	sort.Slice(rejs, func(i, j int) bool {
		if rejs[i].CompartmentID != rejs[j].CompartmentID {
			return rejs[i].CompartmentID < rejs[j].CompartmentID
		}
		return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
	})
	return rejs[0]
}

// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
func rejKindOrder(k ErrorKind) int {
	switch k {
	case ErrOverflow, ErrOverweight:
		return 0
	default:
		return 1
	}
}

// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
func (x *Rejection) firstOffender() string {
	if len(x.OffendingCargo) == 0 {
		return ""
	}
	return x.OffendingCargo[0]
}

// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
// 即视为相同内容，排列顺序不影响判断。卸下操作忽略目标舱位（执行时
// 同样忽略），其目标值不影响内容判断；装载与移动的目标舱位参与比较。
// 编号按去掉首尾空白后的原始字节精确比较：任何字节差异都视为不同内容，
// 包含无效 UTF-8 字节的编号与包含 Unicode 替代字符 U+FFFD 的编号也不相同。
func canonicalKey(ops []Op) string {
	sorted := make([]Op, len(ops))
	for i, op := range ops {
		target := strings.TrimSpace(op.Target)
		if op.Kind == OpUnload {
			target = ""
		}
		sorted[i] = Op{
			Kind:    op.Kind,
			CargoID: strings.TrimSpace(op.CargoID),
			Target:  target,
		}
	}
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Kind != sorted[j].Kind {
			return sorted[i].Kind < sorted[j].Kind
		}
		if sorted[i].CargoID != sorted[j].CargoID {
			return sorted[i].CargoID < sorted[j].CargoID
		}
		return sorted[i].Target < sorted[j].Target
	})
	// 长度前缀编码保留原始字节，不做任何字符集层面的规整，
	// 任意字节内容都不会因分隔符或转义而碰撞。
	var b strings.Builder
	for _, op := range sorted {
		b.WriteString(strconv.Itoa(int(op.Kind)))
		b.WriteByte('|')
		writeRawField(&b, op.CargoID)
		writeRawField(&b, op.Target)
	}
	return b.String()
}

// writeRawField 以“长度:原始字节”的形式写入一个字段。
func writeRawField(b *strings.Builder, s string) {
	b.WriteString(strconv.Itoa(len(s)))
	b.WriteByte(':')
	b.WriteString(s)
}

package stowage

import (
	"sort"
)

// Preview 预演一批装载、卸下、移动操作，返回这批安排按当前配载完成后的
// 预计结果。
//
// 预览是只读的：无论结果能否提交，货物位置、舱位占用与已成功调整记录
// 都不会改变，也不占用任何调整编号。清单沿用与 Adjust 相同的 Op 表示
// 与编号规则，逐条合法性（货物与舱位是否存在、货物状态、重复操作、
// 移动到原舱位等）与正式提交完全一致：某条操作不合法时，按输入顺序
// 返回第一个非法操作的现有错误，不返回局部预览。
//
// 每条操作本身合法时始终返回完整预览：预计配载违反承重或混装限制时
// Submittable 为 false，并在 Rejections 中一次列全全部受影响舱位的
// 拒绝原因；判断以整批操作完成后的最终配载为准，不会因中间步骤暂时
// 超重而拒绝最终合法的交换。
//
// 预览反映调用时刻登记处的一致快照（登记、配载与已成功调整记录取自
// 同一时刻，不会混入并发调整前后的状态）。返回内容是独立快照，调用
// 方修改不影响登记处或之后的预览；状态未变时连续预览同一清单结果
// 一致。正式提交仍以提交时状态重新判断，不能凭旧预览直接放行。
func (r *Registry) Preview(ops []Op) (*PreviewResult, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if len(ops) == 0 {
		return nil, fail(ErrEmptyAdjustment, "", "预览清单不包含任何操作")
	}

	// 与正式提交共用同一套逐条校验与最终配载模拟；预览不带调整编号。
	vops, final, affected, err := r.prepareOps(ops, fail)
	if err != nil {
		return nil, err
	}

	// 涉及货物的原舱位与预计舱位，按货物编号字典序排列。
	cargoChanges := make([]CargoChange, 0, len(vops))
	for _, v := range vops {
		c := v.cargo
		change := CargoChange{CargoID: c.id, From: c.compartmentID}
		switch v.op.Kind {
		case OpLoad, OpMove:
			change.To = v.target.id
		case OpUnload:
			change.To = ""
		}
		cargoChanges = append(cargoChanges, change)
	}
	sort.Slice(cargoChanges, func(i, j int) bool {
		return cargoChanges[i].CargoID < cargoChanges[j].CargoID
	})

	// 受影响舱位调整前后的完整配载，按舱位编号字典序排列。交换中总重量
	// 不变的两个舱位同样列出。
	compIDs := make([]string, 0, len(affected))
	for id := range affected {
		compIDs = append(compIDs, id)
	}
	sort.Strings(compIDs)
	compartments := make([]CompartmentPreview, 0, len(compIDs))
	for _, id := range compIDs {
		compartments = append(compartments, CompartmentPreview{
			ID:     id,
			Before: compartmentView(r.compartments[id]),
			After:  compartmentAfterView(r.compartments[id], final[id]),
		})
	}

	// 预计配载的全部拒绝原因，按舱位编号排列、同舱先重量后混装。
	rejs := r.evaluateFinal(final)
	sort.SliceStable(rejs, func(i, j int) bool {
		if rejs[i].CompartmentID != rejs[j].CompartmentID {
			return rejs[i].CompartmentID < rejs[j].CompartmentID
		}
		return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
	})
	rejections := make([]Rejection, 0, len(rejs))
	for _, rej := range rejs {
		rejections = append(rejections, *cloneRejection(rej))
	}

	return &PreviewResult{
		Submittable:  len(rejections) == 0,
		CargoChanges: cargoChanges,
		Compartments: compartments,
		Rejections:   rejections,
	}, nil
}

// cloneRejection 复制拒绝原因中的切片，保证调用方修改不影响其他结果。
func cloneRejection(x *Rejection) *Rejection {
	cp := &Rejection{
		CompartmentID:   x.CompartmentID,
		Kind:            x.Kind,
		MaxWeight:       x.MaxWeight,
		UsedWeight:      x.UsedWeight,
		RemainingWeight: x.RemainingWeight,
		Overweight:      x.Overweight,
	}
	if x.Destinations != nil {
		cp.Destinations = make([]MixedDestination, len(x.Destinations))
		for i, d := range x.Destinations {
			cp.Destinations[i] = MixedDestination{
				Destination: d.Destination,
				CargoIDs:    append([]string(nil), d.CargoIDs...),
			}
		}
	}
	if x.OffendingCargo != nil {
		cp.OffendingCargo = append([]string(nil), x.OffendingCargo...)
	}
	return cp
}

package stowage

import (
	"math"
	"sort"
)

// cargoView 构造货物快照，重量、目的地与混装许可取登记资料（调用方持锁）。
func cargoView(c *cargo) *CargoView {
	return &CargoView{
		ID:            c.id,
		Weight:        c.weight,
		Destination:   c.destination,
		AllowMixed:    c.allowMixed,
		Loaded:        c.compartmentID != "",
		CompartmentID: c.compartmentID,
	}
}

// compartmentSnapshot 按给定货物集合生成舱位配载快照，是查询实际配载与
// 预览预计配载共用的组装入口：清单按货物编号字典序排列，包含集合中的
// 全部货物；每件货物的重量、目的地与混装许可取登记资料。
//
// projected 为 false 时清单保留货物的真实装载状态与所属舱位（实际配载）；
// 为 true 时一律显示为已装载且属于该舱位（预计配载）。重量合计溢出
// int64 时，已用与剩余重量不提供数值（保持零值），货物清单照常返回。
// 调用方持锁。
func compartmentSnapshot(comp *compartment, set map[string]*cargo, projected bool) CompartmentView {
	ids := make([]string, 0, len(set))
	for cid := range set {
		ids = append(ids, cid)
	}
	sort.Strings(ids)
	views := make([]CargoView, 0, len(ids))
	var used int64
	overflow := false
	for _, cid := range ids {
		c := set[cid]
		view := *cargoView(c)
		if projected {
			// 预计清单中的货物按模拟配载完成后的所属舱位展示；cargoView
			// 返回的是值副本，改写位置字段不影响登记处。
			view.Loaded = true
			view.CompartmentID = comp.id
		}
		views = append(views, view)
		if !overflow {
			if c.weight > math.MaxInt64-used {
				overflow = true
			} else {
				used += c.weight
			}
		}
	}
	view := CompartmentView{
		ID:        comp.id,
		MaxWeight: comp.maxWeight,
		Cargo:     views,
	}
	if !overflow {
		view.UsedWeight = used
		view.RemainingWeight = comp.maxWeight - used
	}
	return view
}

// compartmentView 生成舱位当前实际配载的快照（调用方持锁）。
func compartmentView(comp *compartment) CompartmentView {
	return compartmentSnapshot(comp, comp.cargo, false)
}

// compartmentAfterView 生成舱位在模拟配载下的预计快照（调用方持锁）。
func compartmentAfterView(comp *compartment, set map[string]*cargo) CompartmentView {
	return compartmentSnapshot(comp, set, true)
}

// OpKind 表示调整操作的种类。
type OpKind int

const (
	// OpLoad 装载：将未装载的货物装入目标舱位。
	OpLoad OpKind = iota
	// OpUnload 卸下：将已装载的货物从当前舱位移除，货物记录保留。
	OpUnload
	// OpMove 移动：将已装载的货物直接改放到目标舱位。
	OpMove
)

// String 返回操作种类名称。
func (k OpKind) String() string {
	switch k {
	case OpLoad:
		return "装载"
	case OpUnload:
		return "卸下"
	case OpMove:
		return "移动"
	default:
		return "未知"
	}
}

// Op 是一次调整中的单个操作。
type Op struct {
	Kind    OpKind
	CargoID string
	Target  string // 装载/移动时的目标舱位；卸下时忽略
}

// CargoChange 记录一件货物调整前后的所属舱位。
type CargoChange struct {
	CargoID string
	From    string // 空字符串表示未装载
	To      string // 空字符串表示未装载
}

// CompartmentChange 记录一个舱位调整前后的总重量。
type CompartmentChange struct {
	CompartmentID string
	WeightBefore  int64
	WeightAfter   int64
}

// AdjustmentResult 是一次成功调整的结果快照。
type AdjustmentResult struct {
	ID                 string
	CargoChanges       []CargoChange
	CompartmentChanges []CompartmentChange
}

// CargoView 是货物信息的独立快照。
type CargoView struct {
	ID            string
	Weight        int64
	Destination   string
	AllowMixed    bool
	Loaded        bool
	CompartmentID string // 空字符串表示未装载
}

// CompartmentView 是舱位信息的独立快照。
type CompartmentView struct {
	ID              string
	MaxWeight       int64
	UsedWeight      int64
	RemainingWeight int64
	Cargo           []CargoView // 按编号字典序排列
}

// MixedDestination 描述预计配载中一个舱位内某个目的地对应的全部货物。
type MixedDestination struct {
	Destination string
	CargoIDs    []string // 按编号字典序排列
}

// Rejection 描述预计配载中单个舱位的一条拒绝原因。
//
// Kind 为 ErrOverweight 时，UsedWeight、RemainingWeight、Overweight 与
// MaxWeight 均有效；Kind 为 ErrOverflow（重量溢出）时，预计已用重量、
// 剩余重量与超出量无法用 int64 表示，对应数值字段保持零值，仅提供
// MaxWeight、货物清单与混装原因；Kind 为 ErrMixedLoading 时，
// Destinations 给出各目的地对应的货物，OffendingCargo 列出其中全部
// 不允许混装的货物编号。
type Rejection struct {
	CompartmentID   string
	Kind            ErrorKind
	MaxWeight       int64
	UsedWeight      int64              // 超重时为预计总重量；溢出或混装时为零值
	RemainingWeight int64              // 超重时为预计剩余重量（负值）；其余为零值
	Overweight      int64              // 超重时为超出承重的千克数；其余为零值
	Destinations    []MixedDestination // 混装冲突时各目的地及其货物，按目的地字典序排列
	OffendingCargo  []string           // 混装冲突时全部不允许混装的货物编号，字典序排列
}

// CompartmentPreview 是受影响舱位调整前后的完整配载快照。
// Before 反映调整前配载，清单中的货物保持原所属舱位；After 反映预计
// 配载，清单中的货物一律显示为已装载且属于该舱位，编号、重量、目的地
// 与混装许可仍取登记资料。预计超重时 RemainingWeight 为负值；预计重量
// 溢出 int64 时 After 不提供已用与剩余重量数值（保持零值），货物清单
// 照常返回。
type CompartmentPreview struct {
	ID     string
	Before CompartmentView
	After  CompartmentView
}

// PreviewResult 是一次预览的完整结果，本身是与登记处状态无关的独立快照。
type PreviewResult struct {
	// Submittable 表示按当前登记处状态，这组操作能否作为一次调整提交。
	Submittable bool
	// CargoChanges 列出清单涉及货物的原舱位与预计舱位，按货物编号字典序排列；
	// 未装载用空编号表示。
	CargoChanges []CargoChange
	// Compartments 列出全部受影响舱位调整前后的完整货物清单、已用重量与
	// 剩余重量，按舱位编号字典序排列。即使交换后总重量不变也会列出。
	Compartments []CompartmentPreview
	// Rejections 列出预计配载的全部拒绝原因，按舱位编号排列，同一舱位
	// 先重量（超重/溢出）后混装。为空表示 Submittable 为 true。
	Rejections []Rejection
}

package stowage

import "fmt"

// ErrorKind 描述一次配载操作失败的具体原因。
type ErrorKind int

const (
	// ErrOK 表示没有错误（内部使用）。
	ErrOK ErrorKind = iota
	// ErrInvalidID 编号去掉首尾空白后为空。
	ErrInvalidID
	// ErrInvalidWeight 重量或最大承重不是正整数。
	ErrInvalidWeight
	// ErrInvalidDestination 目的地去掉首尾空白后为空。
	ErrInvalidDestination
	// ErrInvalidOp 操作种类无法识别。
	ErrInvalidOp
	// ErrAlreadyExists 登记对象已存在。
	ErrAlreadyExists
	// ErrNotFound 涉及的货物或舱位不存在。
	ErrNotFound
	// ErrStateMismatch 货物状态与操作不符（未装载或已装载）。
	ErrStateMismatch
	// ErrDuplicateOp 同一调整中货物重复出现，或移动到原舱位。
	ErrDuplicateOp
	// ErrEmptyAdjustment 调整不包含任何操作。
	ErrEmptyAdjustment
	// ErrOverweight 舱位总重量超过最大承重。
	ErrOverweight
	// ErrMixedLoading 不同目的地货物混装，但有货物不允许混装。
	ErrMixedLoading
	// ErrOverflow 重量合计超过 int64 可表示范围。
	ErrOverflow
	// ErrAdjustmentIDConflict 调整编号已用于不同内容。
	ErrAdjustmentIDConflict
)

// String 返回错误原因的中文说明。
func (k ErrorKind) String() string {
	switch k {
	case ErrInvalidID:
		return "编号为空"
	case ErrInvalidWeight:
		return "重量或承重非正整数"
	case ErrInvalidDestination:
		return "目的地为空"
	case ErrInvalidOp:
		return "操作种类无效"
	case ErrAlreadyExists:
		return "对象已存在"
	case ErrNotFound:
		return "对象不存在"
	case ErrStateMismatch:
		return "状态不符"
	case ErrDuplicateOp:
		return "重复操作"
	case ErrEmptyAdjustment:
		return "调整为空"
	case ErrOverweight:
		return "超重"
	case ErrMixedLoading:
		return "混装冲突"
	case ErrOverflow:
		return "重量溢出"
	case ErrAdjustmentIDConflict:
		return "调整编号冲突"
	default:
		return "未知错误"
	}
}

// Error 是配载操作的结构化失败结果，指出涉及的对象与具体原因。
type Error struct {
	Kind         ErrorKind
	ID           string // 涉及的货物或舱位编号，可能为空
	AdjustmentID string // 涉及的调整编号，可能为空
	detail       string
}

func (e *Error) Error() string {
	if e.detail != "" {
		return e.detail
	}
	return e.Kind.String()
}

// fail 构造一个带说明的结构化错误。
func fail(kind ErrorKind, id string, format string, args ...any) *Error {
	return &Error{Kind: kind, ID: id, detail: fmt.Sprintf(format, args...)}
}

// rejectionError 把最终配载评估出的单个拒绝原因转换成正式操作的结构化
// 错误，Adjust 与 AmendCargo 共用同一套对应关系，保证同一种拒绝原因的
// 错误类别、涉及对象与中文说明一致：
// 重量溢出与超重指向舱位，超重说明保留预计总重量与最大承重，溢出不展示
// 无法表示的合计重量；混装冲突指向舱内编号字典序最靠前的一件不允许
// 混装货物（可能原本就在舱内），说明同时指出舱位与该货物。
// failf 决定错误是否携带调整编号：Adjust 传入盖编号的构造函数，
// AmendCargo 直接传入 fail。
func rejectionError(
	rej *Rejection,
	failf func(kind ErrorKind, id string, format string, args ...any) *Error,
) *Error {
	switch rej.Kind {
	case ErrOverflow:
		return failf(ErrOverflow, rej.CompartmentID, "舱位 %s 重量合计超过 int64 可表示范围", rej.CompartmentID)
	case ErrOverweight:
		return failf(ErrOverweight, rej.CompartmentID,
			"舱位 %s 总重量 %d 千克超过最大承重 %d 千克",
			rej.CompartmentID, rej.UsedWeight, rej.MaxWeight)
	default:
		return failf(ErrMixedLoading, rej.firstOffender(),
			"舱位 %s 存在不同目的地货物，但货物 %s 不允许混装",
			rej.CompartmentID, rej.firstOffender())
	}
}

