476		res, err := r.Preview([]Op{
477			{Kind: OpLoad, CargoID: "G4", Target: "C2"},
478			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
479			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
