534			t.Fatal("旧重量 30 移入承重 15 的 C2 应不可提交")
535		}
536		// 更正为 10 后，预览按新资料计算。
537		if err := r.AmendCargo("G1", 10, "Beijing", false); err != nil {
538			t.Fatal(err)
539		}
540		newPreview, err := r.Preview([]Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}})
541		if err != nil {
542			t.Fatal(err)
543		}
544		if !newPreview.Submittable {
545			t.Fatalf("更正后预览应可提交: %+v", newPreview.Rejections)
546		}
547		if newPreview.Compartments[0].After.UsedWeight != 0 {
548			t.Fatalf("预览应按新重量计算原舱位: %+v", newPreview.Compartments[0])
549		}
550		// 旧预览快照仍是旧内容。
551		if oldPreview.Rejections[0].UsedWeight != 30 {
552			t.Fatalf("旧预览应保留更正前内容: %+v", oldPreview.Rejections[0])
553		}
554	}
555	
556	func TestMoveAndUnloadAfterAmendUseNewData(t *testing.T) {
557		r := NewRegistry()
558		if err := r.RegisterCompartment("C1", 100); err != nil {
559			t.Fatal(err)
560		}
561		if err := r.RegisterCompartment("C2", 100); err != nil {
562			t.Fatal(err)
563		}
564		if err := r.RegisterCargo("G1", 30, "Shanghai", true); err != nil {
565			t.Fatal(err)
566		}
567		if _, err := r.Adjust("A0", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}); err != nil {
568			t.Fatal(err)
569		}
570		if err := r.AmendCargo("G1", 40, "Beijing", false); err != nil {
571			t.Fatal(err)
572		}
573		// 移动按新重量计。
574		res, err := r.Adjust("A1", []Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}})
575		if err != nil {
576			t.Fatal(err)
577		}
578		if res.CompartmentChanges[0].WeightBefore != 40 || res.CompartmentChanges[0].WeightAfter != 0 {
579			t.Fatalf("C1 变化错误: %+v", res.CompartmentChanges[0])
580		}
581		if res.CompartmentChanges[1].WeightBefore != 0 || res.CompartmentChanges[1].WeightAfter != 40 {
582			t.Fatalf("C2 应按更正后重量计入: %+v", res.CompartmentChanges[1])
583		}
584		// 卸下收回更正后的重量。
585		res2, err := r.Adjust("A2", []Op{{Kind: OpUnload, CargoID: "G1"}})
586		if err != nil {
587			t.Fatal(err)
588		}
589		if res2.CompartmentChanges[0].WeightBefore != 40 || res2.CompartmentChanges[0].WeightAfter != 0 {
590			t.Fatalf("卸下应收回更正后的重量 40: %+v", res2.CompartmentChanges[0])
591		}
592		cv, _ := r.Cargo("G1")
593		if cv.Loaded || cv.Weight != 40 || cv.Destination != "Beijing" {
594			t.Fatalf("卸下后货物资料错误: %+v", cv)
595		}
596	}
