107		}
108		if len(pv.Compartments) != 2 ||
109			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
110			t.Fatalf("旧预览的受影响舱位不应被改写: %+v", pv.Compartments)
111		}
