148	// 实际配载成功：货物变化为 C3 到 C2；C3 收回 30 千克、C2 增加 30 千克；
149	// C1 不再是受影响舱位，重量不能再次扣减。
150	func TestStalePreviewSubmitAfterInterveningMoveSucceeds(t *testing.T) {
