188		}
189		if !reflect.DeepEqual(res.CargoChanges, []CargoChange{{CargoID: "G1", From: "C3", To: "C2"}}) {
190			t.Fatalf("货物变化应按提交时实际位置记为 C3 到 C2: %+v", res.CargoChanges)
