1	package stowage
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	// 本组回归测试保护这条使用过程：预览通过后更正了货物重量，不重新预览、
10	// 直接提交原安排时，正式提交仍按更正后的重量判断——旧的可提交结果不能
11	// 掩盖最新的超重问题，旧预览快照本身也不能被更正或提交改写。
12	
13	// setupStalePreviewScenario 建立共同的初始场景：
14	// C1、C2 承重均为 100 千克；G1 重 20 千克已装入 C1，G2 重 60 千克已
15	// 装入 C2，G3 重 10 千克尚未装载；三件货物目的地相同，均不允许混装。
16	//
17	// 返回登记处、“把 G1 移到 C2、同时把 G3 装入 C2”的原清单，以及对该
18	// 清单的可提交预览（C2 预计总重量 90 千克）。预览后实际配载保持原样。
19	func setupStalePreviewScenario(t *testing.T) (*Registry, []Op, *PreviewResult) {
20		t.Helper()
21		r := NewRegistry()
22		if err := r.RegisterCompartment("C1", 100); err != nil {
23			t.Fatal(err)
24		}
25		if err := r.RegisterCompartment("C2", 100); err != nil {
26			t.Fatal(err)
27		}
28		if err := r.RegisterCargo("G1", 20, "X", false); err != nil {
29			t.Fatal(err)
30		}
31		if err := r.RegisterCargo("G2", 60, "X", false); err != nil {
32			t.Fatal(err)
33		}
34		if err := r.RegisterCargo("G3", 10, "X", false); err != nil {
35			t.Fatal(err)
36		}
37		if _, err := r.Adjust("A0", []Op{
38			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
39			{Kind: OpLoad, CargoID: "G2", Target: "C2"},
40		}); err != nil {
41			t.Fatal(err)
42		}
43	
44		ops := []Op{
45			{Kind: OpMove, CargoID: "G1", Target: "C2"},
46			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
47		}
48		pv, err := r.Preview(ops)
49		if err != nil {
50			t.Fatal(err)
51		}
52		if !pv.Submittable {
53			t.Fatalf("原清单按 G1 20、G2 60、G3 10 预计 C2 共 90 千克，应可提交: %+v", pv.Rejections)
54		}
55		if len(pv.Compartments) != 2 ||
56			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
57			t.Fatalf("受影响舱位应为 C1、C2: %+v", pv.Compartments)
58		}
59		// C2 预计含三件货物共 90 千克，其中 G1 保留 20 千克。
60		c2After := pv.Compartments[1].After
61		if c2After.UsedWeight != 90 || c2After.RemainingWeight != 10 ||
62			!reflect.DeepEqual(cargoIDs(c2After), []string{"G1", "G2", "G3"}) {
63			t.Fatalf("C2 预计应含三件货物共 90 千克、剩余 10 千克: %+v", c2After)
64		}
65		if c2After.Cargo[0].ID != "G1" || c2After.Cargo[0].Weight != 20 {
66			t.Fatalf("C2 预计清单中 G1 应为 20 千克: %+v", c2After.Cargo)
67		}
68		// C1 预计清空。
69		if c1After := pv.Compartments[0].After; len(c1After.Cargo) != 0 ||
70			c1After.UsedWeight != 0 || c1After.RemainingWeight != 100 {
71			t.Fatalf("C1 预计应清空: %+v", c1After)
72		}
73	
74		// 预览只读：实际配载仍保持原样。
75		c1, _ := r.Compartment("C1")
76		if c1.UsedWeight != 20 || c1.RemainingWeight != 80 ||
77			!reflect.DeepEqual(cargoIDs(*c1), []string{"G1"}) {
78			t.Fatalf("预览后 C1 应保持 G1 一件 20/80: %+v", c1)
79		}
80		c2, _ := r.Compartment("C2")
81		if c2.UsedWeight != 60 || c2.RemainingWeight != 40 ||
82			!reflect.DeepEqual(cargoIDs(*c2), []string{"G2"}) {
83			t.Fatalf("预览后 C2 应保持 G2 一件 60/40: %+v", c2)
84		}
85		g3, _ := r.Cargo("G3")
86		if g3.Loaded || g3.CompartmentID != "" {
87			t.Fatalf("预览后 G3 应仍未装载: %+v", g3)
88		}
89		return r, ops, pv
90	}
91	
92	// assertStalePreviewSnapshot 断言旧预览快照仍保留更正前的内容：
93	// 可提交、货物变化不变、G1 仍重 20 千克、C2 预计仍为 90 千克。
94	func assertStalePreviewSnapshot(t *testing.T, pv *PreviewResult) {
95		t.Helper()
96		if !pv.Submittable || len(pv.Rejections) != 0 {
97			t.Fatalf("旧预览应仍为可提交且无拒绝原因: %+v", pv)
98		}
99		wantChanges := []CargoChange{
100			{CargoID: "G1", From: "C1", To: "C2"},
101			{CargoID: "G3", From: "", To: "C2"},
102		}
103		if !reflect.DeepEqual(pv.CargoChanges, wantChanges) {
104			t.Fatalf("旧预览的货物变化不应被改写: %+v want %+v", pv.CargoChanges, wantChanges)
105		}
106		if len(pv.Compartments) != 2 ||
107			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
108			t.Fatalf("旧预览的舱位清单不应被改写: %+v", pv.Compartments)
109		}
110		c2 := pv.Compartments[1]
111		var g1 *CargoView
112		for i := range c2.After.Cargo {
113			if c2.After.Cargo[i].ID == "G1" {
114				g1 = &c2.After.Cargo[i]
115			}
116		}
117		if g1 == nil {
118			t.Fatalf("旧预览 C2 预计清单仍应包含 G1: %+v", c2.After.Cargo)
119		}
120		if g1.Weight != 20 {
121			t.Fatalf("旧预览应保留 G1 重 20 千克，实际 %d", g1.Weight)
122		}
123		if c2.After.UsedWeight != 90 || c2.After.RemainingWeight != 10 {
124			t.Fatalf("旧预览应保留 C2 预计 90/10 千克: %+v", c2.After)
125		}
126	}
127	
128	// TestStalePreviewSubmitAfterAmendOverweightRejected 覆盖核心回归：
129	// 预览可提交后把 G1 从 20 千克更正为 40 千克，不重新预览直接提交原
130	// 清单，正式提交必须按更正后的重量判断——C2 预计 110 千克超过承重
131	// 100 千克，整次调整拒绝，且不能返回成功调整结果。
132	func TestStalePreviewSubmitAfterAmendOverweightRejected(t *testing.T) {
133		r, ops, old := setupStalePreviewScenario(t)
134	
135		// 更正 G1 重量 20 -> 40；目的地与混装许可保持原值，G1 仍在 C1。
136		if err := r.AmendCargo("G1", 40, "X", false); err != nil {
137			t.Fatalf("更正 G1 重量为 40 千克应成功（C1 仅 40 千克）: %v", err)
138		}
139		g1, _ := r.Cargo("G1")
140		if g1.Weight != 40 || g1.Destination != "X" || g1.AllowMixed ||
141			!g1.Loaded || g1.CompartmentID != "C1" {
142			t.Fatalf("更正后 G1 应以新重量、原目的地与混装许可留在 C1: %+v", g1)
143		}
144	
145		// 保留旧预览，直接用一个未使用过的调整编号提交原来那批操作。
146		res, err := r.Adjust("A1", ops)
147		se := requireError(t, err, ErrOverweight)
148		if res != nil {
149			t.Fatalf("超重时必须拒绝整次调整，不应返回成功调整结果: %+v", res)
150		}
151		if se.ID != "C2" {
152			t.Fatalf("超重错误应指出舱位 C2，实际 ID=%q", se.ID)
153		}
154		if se.AdjustmentID != "A1" {
155			t.Fatalf("超重错误应携带调整编号 A1，实际 %q", se.AdjustmentID)
156		}
157		msg := se.Error()
158		if !strings.Contains(msg, "C2") ||
159			!strings.Contains(msg, "110") || !strings.Contains(msg, "100") {
160			t.Fatalf("超重说明应指出 C2、预计 110 千克与最大承重 100 千克: %s", msg)
161		}
162	
163		// 拒绝后整次调整不生效，资料更正也不能被撤回。
164		g1, _ = r.Cargo("G1")
165		if g1.Weight != 40 || g1.Destination != "X" || g1.AllowMixed ||
166			!g1.Loaded || g1.CompartmentID != "C1" {
167			t.Fatalf("拒绝后 G1 应仍以 40 千克留在 C1（更正不撤回、移动不执行）: %+v", g1)
168		}
169		g2, _ := r.Cargo("G2")
170		if g2.Weight != 60 || !g2.Loaded || g2.CompartmentID != "C2" {
171			t.Fatalf("拒绝后 G2 应仍以 60 千克留在 C2: %+v", g2)
172		}
173		g3, _ := r.Cargo("G3")
174		if g3.Weight != 10 || g3.Loaded || g3.CompartmentID != "" {
175			t.Fatalf("拒绝后 G3 应仍为 10 千克且未装载（不能只执行装载一项）: %+v", g3)
176		}
177		c1, _ := r.Compartment("C1")
178		if c1.UsedWeight != 40 || c1.RemainingWeight != 60 ||
179			!reflect.DeepEqual(cargoIDs(*c1), []string{"G1"}) {
180			t.Fatalf("拒绝后 C1 应为 G1 一件、已用 40 剩余 60: %+v", c1)
181		}
182		c2, _ := r.Compartment("C2")
183		if c2.UsedWeight != 60 || c2.RemainingWeight != 40 ||
184			!reflect.DeepEqual(cargoIDs(*c2), []string{"G2"}) {
185			t.Fatalf("拒绝后 C2 应为 G2 一件、已用 60 剩余 40: %+v", c2)
186		}
187	
188		// 更正与失败提交都不能改写之前保存的旧预览快照。
189		assertStalePreviewSnapshot(t, old)
190	}
191	
192	// TestStalePreviewSubmitAfterAmendExactCapacitySucceeds 保护承重恰好
193	// 相等的边界：G1 更正为 30 千克后直接提交原安排，C2 预计恰为 100
194	// 千克，应成功；返回的舱位重量变化依据提交时的实际重量而非旧预览。
195	func TestStalePreviewSubmitAfterAmendExactCapacitySucceeds(t *testing.T) {
196		r, ops, old := setupStalePreviewScenario(t)
197	
198		// 更正 G1 重量 20 -> 30；目的地与混装许可保持原值。
199		if err := r.AmendCargo("G1", 30, "X", false); err != nil {
200			t.Fatalf("更正 G1 重量为 30 千克应成功: %v", err)
201		}
202		g1, _ := r.Cargo("G1")
203		if g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed ||
204			!g1.Loaded || g1.CompartmentID != "C1" {
205			t.Fatalf("更正后 G1 应以 30 千克留在 C1: %+v", g1)
206		}
207	
208		// 不重新预览，直接用未使用过的编号提交原清单，应成功。
209		res, err := r.Adjust("A1", ops)
210		if err != nil {
211			t.Fatalf("C2 预计恰好 100 千克等于承重，应提交成功: %v", err)
212		}
213		if res == nil || res.ID != "A1" {
214			t.Fatalf("应返回编号为 A1 的成功调整结果: %+v", res)
215		}
216		wantChanges := []CargoChange{
217			{CargoID: "G1", From: "C1", To: "C2"},
218			{CargoID: "G3", From: "", To: "C2"},
219		}
220		if !reflect.DeepEqual(res.CargoChanges, wantChanges) {
221			t.Fatalf("货物变化错误: %+v want %+v", res.CargoChanges, wantChanges)
222		}
223		// 舱位重量变化依据提交时的实际重量（G1 已为 30 千克），
224		// 而不是旧预览中的 20 千克：C1 30 -> 0，C2 60 -> 100。
225		wantCompChanges := []CompartmentChange{
226			{CompartmentID: "C1", WeightBefore: 30, WeightAfter: 0},
227			{CompartmentID: "C2", WeightBefore: 60, WeightAfter: 100},
228		}
229		if !reflect.DeepEqual(res.CompartmentChanges, wantCompChanges) {
230			t.Fatalf("舱位重量变化应按提交时实际重量: %+v want %+v",
231				res.CompartmentChanges, wantCompChanges)
232		}
233	
234		// C1 清空；C2 同时包含三件货物，已用 100 千克、剩余 0 千克。
235		c1, _ := r.Compartment("C1")
236		if c1.UsedWeight != 0 || c1.RemainingWeight != 100 || len(c1.Cargo) != 0 {
237			t.Fatalf("提交后 C1 应清空、已用 0 剩余 100: %+v", c1)
238		}
239		c2, _ := r.Compartment("C2")
240		if c2.UsedWeight != 100 || c2.RemainingWeight != 0 ||
241			c2.MaxWeight != 100 {
242			t.Fatalf("提交后 C2 应已用 100、剩余 0: %+v", c2)
243		}
244		if got := cargoIDs(*c2); !reflect.DeepEqual(got, []string{"G1", "G2", "G3"}) {
245			t.Fatalf("C2 应同时包含三件货物: %v", got)
246		}
247	
248		// 货物查询与舱位清单中的重量、位置一致。
249		wantCargo := map[string]int64{"G1": 30, "G2": 60, "G3": 10}
250		for id, weight := range wantCargo {
251			cv, err := r.Cargo(id)
252			if err != nil {
253				t.Fatal(err)
254			}
255			if !cv.Loaded || cv.CompartmentID != "C2" || cv.Weight != weight {
256				t.Fatalf("货物 %s 查询应为 %d 千克且位于 C2: %+v", id, weight, cv)
257			}
258		}
259		for _, cv := range c2.Cargo {
260			if cv.Weight != wantCargo[cv.ID] || !cv.Loaded || cv.CompartmentID != "C2" {
261				t.Fatalf("舱位清单中 %s 的重量或位置与货物查询不一致: %+v", cv.ID, cv)
262			}
263		}
264	
265		// 成功提交同样不能改写之前保存的旧预览快照。
266		assertStalePreviewSnapshot(t, old)
267	}
